fun reduce(state: PayState, intent: PayIntent): PayState = when (state) {
    is PayState.Idle -> if (intent is PayIntent.Pay) PayState.Authorizing else state
    // حماية تامة: تجاهل أي نداء دفع إضافي أثناء التفويض لمنع الخصم المزدوج!
    is PayState.Authorizing -> state
    else -> state
}
